-- Owner business tools: CRM customers, jobs + expenses, invoices + recorded payments, trade price lists.
CREATE TABLE IF NOT EXISTS customers(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,name TEXT NOT NULL,email TEXT NOT NULL DEFAULT '',phone TEXT NOT NULL DEFAULT '',address TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'lead' CHECK(status IN ('lead','quoted','active','past')),source TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS customers_company ON customers(company_id,status);
CREATE TABLE IF NOT EXISTS customer_notes(id INTEGER PRIMARY KEY AUTOINCREMENT,customer_id INTEGER NOT NULL REFERENCES customers(id) ON DELETE CASCADE,text TEXT NOT NULL,by_name TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS biz_jobs(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,customer_id INTEGER REFERENCES customers(id) ON DELETE SET NULL,estimate_id INTEGER,name TEXT NOT NULL,address TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'planned' CHECK(status IN ('planned','active','done')),contract_amount REAL NOT NULL DEFAULT 0,start_date TEXT NOT NULL DEFAULT '',end_date TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS expenses(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,job_id INTEGER REFERENCES biz_jobs(id) ON DELETE SET NULL,category TEXT NOT NULL DEFAULT 'Materials',amount REAL NOT NULL,spent_on TEXT NOT NULL,vendor TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS invoices(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,number TEXT NOT NULL,customer_id INTEGER REFERENCES customers(id) ON DELETE SET NULL,job_id INTEGER REFERENCES biz_jobs(id) ON DELETE SET NULL,to_name TEXT NOT NULL DEFAULT '',to_email TEXT NOT NULL DEFAULT '',items TEXT NOT NULL DEFAULT '[]',tax_rate REAL NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','sent','void')),issued_on TEXT NOT NULL,due_on TEXT NOT NULL DEFAULT '',notes TEXT NOT NULL DEFAULT '',sent_at TEXT,created_at TEXT NOT NULL,UNIQUE(company_id,number));
CREATE TABLE IF NOT EXISTS invoice_payments(id INTEGER PRIMARY KEY AUTOINCREMENT,invoice_id INTEGER NOT NULL REFERENCES invoices(id) ON DELETE CASCADE,amount REAL NOT NULL,method TEXT NOT NULL DEFAULT 'Other',paid_on TEXT NOT NULL,note TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS price_items(id INTEGER PRIMARY KEY AUTOINCREMENT,company_id INTEGER NOT NULL REFERENCES companies(id) ON DELETE CASCADE,trade TEXT NOT NULL,name TEXT NOT NULL,unit TEXT NOT NULL DEFAULT 'ea',price REAL NOT NULL DEFAULT 0,cost REAL NOT NULL DEFAULT 0,note TEXT NOT NULL DEFAULT '');
PRAGMA user_version=16;
